    private static String clip(Pc1Raster.Clip c){return csv(c.left,c.top,c.right,c.bottom);}
    private static String rect(Pc1Raster.Rect r){return csv(r.left,r.top,r.right,r.bottom);}
    private static byte[] save(Pc1Compositor c)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();c.save(new DataOutputStream(b));return b.toByteArray();}
    private static Pc1Compositor load(byte[] b)throws Exception{return Pc1Compositor.load(new DataInputStream(new ByteArrayInputStream(b)));}
