        public void writeInt(int a,int v){values.put(a,v);}
        public void writeByte(int a,int v){values.put(a,(readInt(a)&~255)|(v&255));}
        String csv(){int[] v=new int[STATE.length];for(int i=0;i<v.length;i++)v[i]=readInt(STATE[i]);return Pc1CompositorTests.csv(v);}
